struct ForceScalarGuard {
  explicit ForceScalarGuard(bool force_scalar) : old_force_scalar(util::force_scalar()) {
    util::set_force_scalar_for_testing(force_scalar);
  }
  ~ForceScalarGuard() { util::set_force_scalar_for_testing(old_force_scalar); }

  bool old_force_scalar;
};

TEST(CdnaVop3pPackedF32Test, SgprSourcesReadBothRegisters) {
  struct ArchCase {
    rj_code_arch_t arch;
    std::string_view name;
    uint32_t sgprs_per_wf;
  };

  constexpr ArchCase arch_cases[] = {
      {ROCJITSU_CODE_ARCH_CDNA3, "cdna3", 106},
      {ROCJITSU_CODE_ARCH_CDNA4, "cdna4", 106},
      {ROCJITSU_CODE_ARCH_CDNA5, "gfx1250", 128},
  };

  for (const auto &arch : arch_cases) {
    for (bool force_scalar : {false, true}) {
      ForceScalarGuard guard(force_scalar);
      const std::string suffix = force_scalar ? "_scalar" : "_simd";
      amdgpu::GpuMemory gpu_mem(std::string(arch.name) + "_pk_f32_sgpr_mem" + suffix);
      amdgpu::L2Cache l2(std::string(arch.name) + "_pk_f32_sgpr_l2" + suffix);

      amdgpu::ComputeUnitCore::Config cfg{};
      cfg.arch = arch.arch;
      cfg.num_wf_slots = 1;
      cfg.sgprs_per_wf = arch.sgprs_per_wf;
      cfg.vgprs_per_wf = 256;
      cfg.lds_size_kb = 64;

      auto cu = amdgpu::ComputeUnitCore::create(std::string(arch.name), cfg, &gpu_mem, &l2);
      ASSERT_NE(cu, nullptr);
      auto decoder = Decoder::create(arch.arch);
      ASSERT_NE(decoder, nullptr);
      auto *wf = cu->dispatch_wf(0, 0, cfg.sgprs_per_wf, cfg.vgprs_per_wf);
      ASSERT_NE(wf, nullptr);
      wf->set_exec(~uint64_t{0});

      const uint32_t vb = wf->vgpr_alloc().base;
      const uint32_t sb = wf->sgpr_alloc().base;
      cu->write_sgpr(sb + 8, std::bit_cast<uint32_t>(4.0f));
      cu->write_sgpr(sb + 9, std::bit_cast<uint32_t>(5.0f));
      for (uint32_t lane = 0; lane < wf->wf_size(); ++lane) {
        cu->write_vgpr(vb + 0, lane, std::bit_cast<uint32_t>(2.0f));
        cu->write_vgpr(vb + 1, lane, std::bit_cast<uint32_t>(3.0f));
      }

      std::array<uint32_t, 2> words{};
      switch (arch.arch) {
      case ROCJITSU_CODE_ARCH_CDNA3:
        words =
            cdna3::build_vop3p(cdna3::kVPkFmaF32Vop3p, {.vdst = 2,
                                                        .op_sel_hi_2 = 1,
                                                        .src0 = cdna3::OPR_SRC_NOLIT_VGPR_MIN,
                                                        .src1 = cdna3::OPR_SRC_SIMPLE_SGPR_MIN + 8,
                                                        .src2 = cdna3::OPR_SRC_SIMPLE_POS_INT_MIN,
                                                        .op_sel_hi = 3});
        break;
      case ROCJITSU_CODE_ARCH_CDNA4:
        words =
            cdna4::build_vop3p(cdna4::kVPkFmaF32Vop3p, {.vdst = 2,
                                                        .op_sel_hi_2 = 1,
                                                        .src0 = cdna4::OPR_SRC_NOLIT_VGPR_MIN,
                                                        .src1 = cdna4::OPR_SRC_SIMPLE_SGPR_MIN + 8,
                                                        .src2 = cdna4::OPR_SRC_SIMPLE_POS_INT_MIN,
                                                        .op_sel_hi = 3});
        break;
      case ROCJITSU_CODE_ARCH_CDNA5:
        words = cdna5::build_vop3p(cdna5::kVPkFmaF32Vop3p, {.vdst = 2,
                                                            .src0 = cdna5::OPR_SRC_VGPR_MIN,
                                                            .src1 = cdna5::OPR_SRC_SGPR_MIN + 8,
                                                            .src2 = cdna5::OPR_SRC_POS_INT_MIN,
                                                            .opsel_hi = 3});
        words[0] |= uint32_t{1} << 14; // op_sel_hi_2 is the src2 high-half selector.
        break;
      default:
        FAIL() << "unsupported architecture " << arch.name;
      }
      std::unique_ptr<Instruction> inst(decode_valid(*decoder, words.data()));
      ASSERT_NE(inst, nullptr) << arch.name;
      ASSERT_EQ(std::string_view(inst->mnemonic()), "v_pk_fma_f32") << arch.name;
      cu->execute_instruction(inst.get(), *wf);

      for (uint32_t lane = 0; lane < wf->wf_size(); ++lane) {
        EXPECT_EQ(cu->read_vgpr(vb + 2, lane), std::bit_cast<uint32_t>(8.0f))
            << arch.name << " force_scalar=" << force_scalar << " lane " << lane;
        EXPECT_EQ(cu->read_vgpr(vb + 3, lane), std::bit_cast<uint32_t>(15.0f))
            << arch.name << " force_scalar=" << force_scalar << " lane " << lane;
      }

      if (!wf->is_halted())
        wf->halt();
    }
  }
}

class Gfx1250MemoryTestCu
    : public amdgpu::IsaExecComputeUnit<simdojo::ExecMode::FUNCTIONAL, cdna5::Isa> {
public:
  using Base = amdgpu::IsaExecComputeUnit<simdojo::ExecMode::FUNCTIONAL, cdna5::Isa>;

  Gfx1250MemoryTestCu(std::string name, const amdgpu::ComputeUnitCore::Config &config,
                      amdgpu::GpuMemory *memory, amdgpu::L2Cache *l2)
      : Base(std::move(name), config, memory, l2) {
    if (l2)
      l2->set_backing_memory(memory);
    set_memory(memory);
    set_l2(l2);
  }

  void execute_and_route(Instruction *inst, amdgpu::Wavefront &wf) {
    execute_instruction(inst, wf);
    if (inst->is_memory_op())
      route_memory_inst(inst, wf);
    else
      delete inst;
  }
};

