TEST(Rdna4True16Vop3Test, AddF16DppPreservesMaskedDestinationHalf) {
  ForceScalarGuard guard(false);
  ScopedIsaExecutionBackend execution_backend_scope{&rdna4::execution_backend()};
  amdgpu::GpuMemory gpu_mem("rdna4_true16_add_f16_dpp_mem");
  amdgpu::L2Cache l2("rdna4_true16_add_f16_dpp_l2");

  amdgpu::ComputeUnitCore::Config cfg{};
  cfg.arch = ROCJITSU_CODE_ARCH_RDNA4;
  cfg.num_wf_slots = 1;
  cfg.sgprs_per_wf = 106;
  cfg.vgprs_per_wf = 256;
  cfg.lds_size_kb = 64;

  auto cu = amdgpu::ComputeUnitCore::create("rdna4_true16_add_f16_dpp", cfg, &gpu_mem, &l2);
  ASSERT_NE(cu, nullptr);

  auto *wf = cu->dispatch_wf(0, 0, cfg.sgprs_per_wf, cfg.vgprs_per_wf);
  ASSERT_NE(wf, nullptr);
  ASSERT_EQ(wf->wf_size(), 32u);
  wf->set_exec((1ULL << wf->wf_size()) - 1ULL);

  const uint32_t vb = wf->vgpr_alloc().base;
  constexpr uint32_t kSrc0 = 0;
  constexpr uint32_t kSrc1 = 1;
  constexpr uint32_t kDst = 2;

  for (uint32_t lane = 0; lane < wf->wf_size(); ++lane) {
    cu->write_vgpr(vb + kSrc0, lane,
                   pack16(0x1111u, util::f32_to_f16(static_cast<float>(lane + 10))));
    cu->write_vgpr(vb + kSrc1, lane, pack16(0x2222u, util::f32_to_f16(0.5f)));
    cu->write_vgpr(
        vb + kDst, lane,
        pack16(static_cast<uint16_t>(0x4000u + lane), static_cast<uint16_t>(0x7000u + lane)));
  }

  rdna4::Vop3VopDpp16MachineInst raw{};
  raw.vdst = kDst;
  raw.opsel = 0xBu;
  raw.op = 0x132u;
  raw.encoding = 0x35u;
  raw.src0 = amdgpu::SRC_DPP;
  raw.src1 = 256u + kSrc1;
  raw.vsrc0 = kSrc0;
  raw.dpp_ctrl = amdgpu::dpp::ROW_SHR1;
  raw.fi = 1;
  raw.bound_ctrl = 0;
  raw.bank_mask = 0xFu;
  raw.row_mask = 0x1u;

  rdna4::VAddF16Vop3 inst(reinterpret_cast<const rdna4::MachineInst *>(&raw));
  ASSERT_EQ(std::string_view(inst.mnemonic()), "v_add_f16");
  inst.execute_impl(*wf);

  EXPECT_EQ(cu->read_vgpr(vb + kDst, 0), pack16(0x4000u, 0x7000u));
  EXPECT_EQ(cu->read_vgpr(vb + kDst, 1), pack16(0x4001u, util::f32_to_f16(10.5f)));
  EXPECT_EQ(cu->read_vgpr(vb + kDst, 2), pack16(0x4002u, util::f32_to_f16(11.5f)));
  EXPECT_EQ(cu->read_vgpr(vb + kDst, 16), pack16(0x4010u, 0x7010u));

  if (!wf->is_halted())
    wf->halt();
}

TEST(Rdna4True16Vop3Test, UnaryDpp16ScalarAndSimdMatchMaskedLaneRouting) {
  if constexpr (!util::has_stdx_simd) {
    GTEST_SKIP() << "<experimental/simd> unavailable";
  }

  constexpr uint32_t kWaveSize = 32;
  constexpr uint32_t kSrc = 0;
  constexpr uint32_t kDst = 2;
  constexpr uint32_t kDppCtrl = amdgpu::dpp::ROW_SHR1;
  constexpr uint32_t kRowMask = 0b0101;
  constexpr uint32_t kBankMask = 0b1010;
  constexpr uint64_t kExec = (uint64_t{1} << kWaveSize) - 1;
  std::array<std::array<uint32_t, kWaveSize>, 2> outputs{};

  for (uint32_t mode = 0; mode < outputs.size(); ++mode) {
    const bool force_scalar = mode == 0;
    SCOPED_TRACE(force_scalar ? "scalar" : "simd");
    ForceScalarGuard guard(force_scalar);
    amdgpu::GpuMemory gpu_mem(force_scalar ? "rdna4_true16_unary_dpp_scalar_mem"
                                           : "rdna4_true16_unary_dpp_simd_mem");
    amdgpu::L2Cache l2(force_scalar ? "rdna4_true16_unary_dpp_scalar_l2"
                                    : "rdna4_true16_unary_dpp_simd_l2");

    amdgpu::ComputeUnitCore::Config cfg{};
    cfg.arch = ROCJITSU_CODE_ARCH_RDNA4;
    cfg.num_wf_slots = 1;
    cfg.sgprs_per_wf = 106;
    cfg.vgprs_per_wf = 256;
    cfg.lds_size_kb = 64;
    auto cu = amdgpu::ComputeUnitCore::create("rdna4_true16_unary_dpp", cfg, &gpu_mem, &l2);
    ASSERT_NE(cu, nullptr);
    auto *wf = cu->dispatch_wf(0, 0, cfg.sgprs_per_wf, cfg.vgprs_per_wf);
    ASSERT_NE(wf, nullptr);
    ASSERT_EQ(wf->wf_size(), kWaveSize);
    wf->set_exec(kExec);

    const uint32_t vb = wf->vgpr_alloc().base;
    for (uint32_t lane = 0; lane < kWaveSize; ++lane) {
      const float value = static_cast<float>(uint32_t{1} << (lane % 4));
      cu->write_vgpr(vb + kSrc, lane, pack16(0xCAFEu, util::f32_to_f16(value)));
      cu->write_vgpr(
          vb + kDst, lane,
          pack16(static_cast<uint16_t>(0x5000u + lane), static_cast<uint16_t>(0x1000u + lane)));
    }

    rdna4::Vop3VopDpp16MachineInst raw{};
    raw.vdst = kDst;
    raw.opsel = 0x9u; // Select high src0 and high destination halves.
    raw.op = rdna4::kVRcpF16Vop3;
    raw.encoding = 0x35u;
    raw.src0 = amdgpu::SRC_DPP;
    raw.vsrc0 = kSrc;
    raw.dpp_ctrl = kDppCtrl;
    raw.fi = 1;
    raw.bound_ctrl = 0;
    raw.bank_mask = kBankMask;
    raw.row_mask = kRowMask;

    static_assert(sizeof(raw) == 3 * sizeof(uint32_t));
    auto decoder = Decoder::create(ROCJITSU_CODE_ARCH_RDNA4);
    std::unique_ptr<Instruction> inst(
        decode_valid(*decoder, reinterpret_cast<const uint32_t *>(&raw)));
    ASSERT_NE(inst, nullptr);
    ASSERT_EQ(std::string_view(inst->mnemonic()), "v_rcp_f16");
    cu->execute_instruction(inst.get(), *wf);
    for (uint32_t lane = 0; lane < kWaveSize; ++lane)
      outputs[mode][lane] = cu->read_vgpr(vb + kDst, lane);

    if (!wf->is_halted())
      wf->halt();
  }

  EXPECT_EQ(outputs[0], outputs[1]);
  const auto plan = amdgpu::dpp::make_dpp_plan(kWaveSize, kDppCtrl, kRowMask, kBankMask,
                                               /*bound_ctrl=*/0, /*fi=*/1, kExec,
                                               /*inactive_uses_bound_ctrl=*/true);
  for (uint32_t lane = 0; lane < kWaveSize; ++lane) {
    const int source_lane = plan.source_lanes[lane];
    const bool writes_destination =
        (plan.row_bank_mask & plan.source_write_mask & (uint64_t{1} << lane)) != 0;
    const uint16_t expected_high =
        !writes_destination || source_lane == amdgpu::dpp::DppPlan::INVALID_LANE
            ? static_cast<uint16_t>(0x1000u + lane)
            : util::f32_to_f16(1.0f / static_cast<float>(uint32_t{1} << (source_lane % 4)));
    EXPECT_EQ(outputs[1][lane], pack16(static_cast<uint16_t>(0x5000u + lane), expected_high))
        << "lane " << lane;
  }
}

