    SCOPED_TRACE(arch_case.name);
    amdgpu::GpuMemory gpu_mem(std::string("hwreg_partial_mem_") + arch_case.name);
    amdgpu::L2Cache l2(std::string("hwreg_partial_l2_") + arch_case.name);

